frappe.query_reports["Sales Register Main Rohan"] = {
    filters_set: function (filters) {
        const today = frappe.datetime.get_today();
        const past_30 = frappe.datetime.add_days(today, -30);

        if (!filters.start_date) {
            frappe.query_report.set_filter_value('start_date', past_30);
        }
        if (!filters.end_date) {
            frappe.query_report.set_filter_value('end_date', today);
        }

        if (!filters.start_date && !filters.end_date) {
            frappe.query_report.refresh();
        }
    }
};

